  141: /// ordinary reports pass through untouched. The result never exceeds
  142: /// `max_bytes`: a bound too small for [`TRUNCATION_MARKER`] keeps
  143: /// content over annotation rather than overshoot (unreachable for the
  144: /// constants above, but the bound is honored unconditionally).
  145: fn bounded_head(value: &str, max_bytes: usize) -> String {
  146:     if value.len() <= max_bytes {
  147:         return value.to_string();
  148:     }
  149:     if max_bytes <= TRUNCATION_MARKER.len() {
  150:         return value[..floor_char_boundary(value, max_bytes)].to_string();
  151:     }
  152:     let end = floor_char_boundary(value, max_bytes - TRUNCATION_MARKER.len());
  153:     let mut bounded = String::with_capacity(end + TRUNCATION_MARKER.len());
  154:     bounded.push_str(&value[..end]);
  155:     bounded.push_str(TRUNCATION_MARKER);
  156:     bounded
  157: }
  158: 
  159: /// `value` bounded to `max_bytes`, keeping its TAIL and marking the cut.
  160: /// Same byte guarantee and same byte-identical passthrough as
  161: /// [`bounded_head`]; used for the path, whose tail is the filename.
  162: fn bounded_tail(value: &str, max_bytes: usize) -> String {
  163:     if value.len() <= max_bytes {
  164:         return value.to_string();
  165:     }
  166:     if max_bytes <= TRUNCATION_MARKER.len() {
  167:         let start = ceil_char_boundary(value, value.len() - max_bytes);
  168:         return value[start..].to_string();
  169:     }
  170:     let keep = max_bytes - TRUNCATION_MARKER.len();
  171:     let start = ceil_char_boundary(value, value.len() - keep);
  172:     let mut bounded = String::with_capacity(TRUNCATION_MARKER.len() + value.len() - start);
  173:     bounded.push_str(TRUNCATION_MARKER);
  174:     bounded.push_str(&value[start..]);
  175:     bounded
  176: }
