  180: /// wire path, empty for the single-file destination convention (the
  181: /// destination root IS the file — same rule as `FileHeader`).
  182: #[derive(Debug, Default, Clone, PartialEq, Eq)]
  183: pub struct FileFailure {
  184:     pub relative_path: String,
  185:     pub reason: String,
  186:     /// The failed entry's exact name bytes when they are not the text's —
  187:     /// set where the failure is made, so a name that collides with another
  188:     /// in its lossy text still names its own file (review cr-jl3afix1-1).
  189:     pub raw_relative_path: Option<Vec<u8>>,
  190: }
