  192: impl FileFailure {
  193:     /// Wire form of one contained failure (contract v6), per-entry
  194:     /// bounded (cr-pfc4-2).
  195:     ///
  196:     /// The per-string bounds live HERE, not at the call site, so no
  197:     /// producer of a wire entry can put an unbounded string on the
  198:     /// closing summary frame: `reason` keeps its head up to
  199:     /// [`MAX_FAILURE_REASON_BYTES`], `relative_path` keeps its tail up
  200:     /// to [`MAX_FAILURE_PATH_BYTES`]. Both cut on a char boundary and
  201:     /// mark the cut; anything already inside its bound is copied
  202:     /// byte-identically. The in-memory record keeps its full strings —
  203:     /// the bound is the wire's, and the whole reason is already in the
  204:     /// log `record_failure` wrote.
  205:     pub fn to_wire(&self) -> crate::generated::FileFailure {
  206:         crate::generated::FileFailure {
  207:             relative_path: bounded_tail(&self.relative_path, MAX_FAILURE_PATH_BYTES),
  208:             reason: bounded_head(&self.reason, MAX_FAILURE_REASON_BYTES),
  209:             // A cut name is no identity: bytes past the bound are dropped
  210:             // whole, and the text stands alone.
  211:             raw_relative_path: self
  212:                 .raw_relative_path
  213:                 .clone()
  214:                 .filter(|raw| raw.len() <= MAX_FAILURE_PATH_BYTES)
  215:                 .unwrap_or_default(),
  216:         }
  217:     }
