  219:     /// The inverse, for a caller reading a peer's summary back into the
  220:     /// in-memory report (the local summary surface, pfc-5's renderer).
  221:     pub fn from_wire(wire: &crate::generated::FileFailure) -> Self {
  222:         Self {
  223:             relative_path: wire.relative_path.clone(),
  224:             reason: wire.reason.clone(),
  225:             raw_relative_path: (!wire.raw_relative_path.is_empty())
  226:                 .then(|| wire.raw_relative_path.clone()),
  227:         }
