  231: /// A path set in wire form: sorted, bounded by
  232: /// [`MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES`], `(paths, truncated)`.
  233: fn wire_path_set(set: &std::collections::HashSet<String>) -> (Vec<String>, bool) {
  234:     let mut paths: Vec<&String> = set.iter().collect();
  235:     paths.sort();
  236:     let mut out = Vec::new();
  237:     let mut remaining = MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES;
  238:     for path in paths {
  239:         let cost = path.len().saturating_add(4);
  240:         if cost > remaining {
  241:             return (out, true);
  242:         }
  243:         remaining -= cost;
  244:         out.push(path.clone());
  245:     }
  246:     (out, false)
  247: }
